<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Informacje systemowe'; ?>
<div class="page-head"><div><p class="eyebrow">Administracja</p><h1>Informacje systemowe</h1></div></div>
<section class="card"><dl class="system-list"><dt>imWiki</dt><dd><?=Html::e(IMWIKI_VERSION)?></dd><dt>PHP</dt><dd><?=Html::e($phpVersion)?></dd><dt>Baza</dt><dd><?=Html::e($dbVersion)?></dd><dt>Serwer WWW</dt><dd><?=Html::e($server)?></dd><dt>Upload</dt><dd><?=Html::e($upload)?></dd><dt>Storage writable</dt><dd><?=$storageWritable?'Tak':'Nie'?></dd><dt>Timezone</dt><dd><?=Html::e($timezone)?></dd><dt>Request ID</dt><dd><?=Html::e($requestId??IMWIKI_REQUEST_ID)?></dd><dt>Pending jobs</dt><dd><?=Html::e($pendingJobs)?></dd><dt>Failed jobs</dt><dd><?=Html::e($failedJobs)?></dd><dt>Wolne miejsce</dt><dd><?=$diskFree!==null?Html::e(number_format($diskFree/1024/1024/1024,2)).' GiB':'n/d'?></dd></dl></section>
<section class="card section-card"><h2>Workflow statusów stron</h2><p class="muted">Domyślnie wyłączony. Po włączeniu dostępne są Szkic → Przegląd → Zatwierdzona → Opublikowana oraz trwała historia decyzji.</p><form method="post" action="<?=Html::e(Url::to('/admin/workflow'))?>"><?=Csrf::field()?><input type="hidden" name="enabled" value="<?=$workflowEnabled?'0':'1'?>"><button class="button <?=$workflowEnabled?'secondary':''?>"><?=$workflowEnabled?'Wyłącz workflow':'Włącz workflow'?></button></form></section>
<section class="card section-card"><h2>Public sharing</h2><p class="muted">Domyślnie wyłączony. Po włączeniu właściciel lub administrator strony może utworzyć losowy link z opcjonalnym hasłem i datą wygaśnięcia.</p><form method="post" action="<?=Html::e(Url::to('/admin/public-sharing'))?>"><?=Csrf::field()?><input type="hidden" name="enabled" value="<?=$publicSharingEnabled?'0':'1'?>"><button class="button <?=$publicSharingEnabled?'secondary':''?>"><?=$publicSharingEnabled?'Wyłącz Public sharing':'Włącz Public sharing'?></button></form></section>
<section class="card section-card"><h2>Maintenance mode</h2><p class="muted">Zwykli użytkownicy zobaczą stronę konserwacji. Administrator może nadal się zalogować i wejść do administracji.</p><form method="post" action="<?=Html::e(Url::to('/admin/maintenance'))?>"><?=Csrf::field()?><input type="hidden" name="enabled" value="<?=$maintenanceEnabled?'0':'1'?>"><button class="button <?=$maintenanceEnabled?'secondary':''?>"><?=$maintenanceEnabled?'Wyłącz Maintenance mode':'Włącz Maintenance mode'?></button></form></section>
